#!/usr/bin/env python3
"""Export Thunderbird Personal Address Book (abook.sqlite) to CSV."""
import csv
import re
import sqlite3
import sys

DB = '/tmp/abook_copy.sqlite'
OUT = '/home/user/Desktop/contacts.csv'

HEADERS = [
    "First Name", "Last Name", "Display Name", "Nickname",
    "Primary Email", "Secondary Email", "Screen Name",
    "Work Phone", "Home Phone", "Fax Number", "Pager Number", "Mobile Number",
    "Home Address", "Home Address 2", "Home City", "Home State",
    "Home ZipCode", "Home Country",
    "Work Address", "Work Address 2", "Work City", "Work State",
    "Work ZipCode", "Work Country",
    "Job Title", "Department", "Organization",
    "Web Page 1", "Web Page 2",
    "Birth Year", "Birth Month", "Birth Day",
    "Custom 1", "Custom 2", "Custom 3", "Custom 4", "Notes",
]


def unfold(vcard_text):
    # vCard line folding: lines starting with space/tab continue previous line
    out = []
    for line in vcard_text.splitlines():
        if line.startswith((' ', '\t')) and out:
            out[-1] += line[1:]
        else:
            out.append(line)
    return out


def split_escaped(s, sep):
    # Split on `sep` but respect backslash escapes
    parts, buf, i = [], [], 0
    while i < len(s):
        c = s[i]
        if c == '\\' and i + 1 < len(s):
            buf.append(s[i:i + 2])
            i += 2
            continue
        if c == sep:
            parts.append(''.join(buf))
            buf = []
        else:
            buf.append(c)
        i += 1
    parts.append(''.join(buf))
    return parts


def unescape(s):
    return s.replace('\\n', '\n').replace('\\,', ',').replace('\\;', ';').replace('\\\\', '\\')


def parse_vcard(vcard_text):
    rec = {h: '' for h in HEADERS}
    for line in unfold(vcard_text):
        if ':' not in line:
            continue
        head, _, value = line.partition(':')
        name, *param_list = head.split(';')
        params = {}
        for p in param_list:
            if '=' in p:
                k, v = p.split('=', 1)
                params[k.upper()] = v
            else:
                params[p.upper()] = ''
        name = name.upper()

        if name == 'FN':
            rec["Display Name"] = unescape(value)
        elif name == 'N':
            comps = split_escaped(value, ';')
            comps += [''] * (5 - len(comps))
            rec["Last Name"] = unescape(comps[0])
            rec["First Name"] = unescape(comps[1])
        elif name == 'NICKNAME':
            rec["Nickname"] = unescape(value)
        elif name == 'EMAIL':
            if not rec["Primary Email"]:
                rec["Primary Email"] = unescape(value)
            elif not rec["Secondary Email"]:
                rec["Secondary Email"] = unescape(value)
        elif name == 'TEL':
            t = params.get('TYPE', '').lower()
            v = unescape(value)
            if 'cell' in t or 'mobile' in t:
                rec["Mobile Number"] = v
            elif 'work' in t:
                rec["Work Phone"] = v
            elif 'fax' in t:
                rec["Fax Number"] = v
            elif 'pager' in t:
                rec["Pager Number"] = v
            else:
                rec["Home Phone"] = v
        elif name == 'ADR':
            comps = split_escaped(value, ';')
            comps += [''] * (7 - len(comps))
            po_box, ext, street, locality, region, postal, country = comps[:7]
            t = params.get('TYPE', '').lower()
            prefix = "Work" if 'work' in t else "Home"
            rec[f"{prefix} Address"] = unescape(street or ext)
            rec[f"{prefix} Address 2"] = unescape(ext if street else '')
            rec[f"{prefix} City"] = unescape(locality)
            rec[f"{prefix} State"] = unescape(region)
            rec[f"{prefix} ZipCode"] = unescape(postal)
            rec[f"{prefix} Country"] = unescape(country)
        elif name == 'BDAY':
            v = value.strip()
            m = re.match(r'^(\d{4})-?(\d{2})-?(\d{2})$', v)
            if m:
                rec["Birth Year"] = m.group(1)
                rec["Birth Month"] = m.group(2)
                rec["Birth Day"] = m.group(3)
        elif name == 'TITLE':
            rec["Job Title"] = unescape(value)
        elif name == 'ORG':
            comps = split_escaped(value, ';')
            rec["Organization"] = unescape(comps[0]) if comps else ''
            if len(comps) > 1:
                rec["Department"] = unescape(comps[1])
        elif name == 'URL':
            if not rec["Web Page 1"]:
                rec["Web Page 1"] = unescape(value)
            elif not rec["Web Page 2"]:
                rec["Web Page 2"] = unescape(value)
        elif name == 'NOTE':
            rec["Notes"] = unescape(value)
    return rec


def main():
    con = sqlite3.connect(DB)
    cur = con.cursor()
    cur.execute("SELECT card, value FROM properties WHERE name='_vCard' ORDER BY card")
    rows = []
    for _card, vcard in cur.fetchall():
        rows.append(parse_vcard(vcard))
    con.close()

    rows.sort(key=lambda r: (r["Display Name"].lower(), r["Last Name"].lower()))

    with open(OUT, 'w', newline='', encoding='utf-8') as f:
        w = csv.DictWriter(f, fieldnames=HEADERS, quoting=csv.QUOTE_MINIMAL)
        w.writeheader()
        w.writerows(rows)
    print(f"Wrote {len(rows)} contacts to {OUT}")


if __name__ == '__main__':
    main()

